  8	    public BTreeNode(int minimumDegree, boolean leaf) {
  9	        this.keys = new int[2 * minimumDegree - 1];
 10	        this.minimumDegree = minimumDegree;
 11	        this.children = new BTreeNode[2 * minimumDegree];
 12	        this.keyCount = 0;
 13	        this.leaf = leaf;
 14	    }
 15	
 16	    static BTreeNode leafWithSingleKey(int minimumDegree, int key) {
 17	        BTreeNode node = new BTreeNode(minimumDegree, true);
 18	        node.initializeWithSingleKey(key);
 19	        return node;
 20	    }
 21	
 22	    static BTreeNode internalRootWithFirstChild(int minimumDegree, BTreeNode firstChild) {
 23	        BTreeNode node = new BTreeNode(minimumDegree, false);
 24	        node.setChild(0, firstChild);
 25	        return node;
 26	    }
 27	
 28	    private void initializeWithSingleKey(int key) {
 29	        keys[0] = key;
 30	        keyCount = 1;
 31	    }
 32	
 33	    private void setChild(int index, BTreeNode child) {
 34	        children[index] = child;
 35	    }
 36	
 37	    boolean isFull() {
 38	        return keyCount == maxKeys();
 39	    }
 40	
 41	    private int maxKeys() {
 42	        return 2 * minimumDegree - 1;
 43	    }
 44	
 45	    private int insertionPosition(int key) {
 46	        int index = keyCount - 1;
 47	        while (index >= 0 && keys[index] > key) {
 48	            index--;
 49	        }
 50	        return index + 1;
 51	    }
 52	
 53	    void insertNonFull(int key) {
 54	        if (leaf) {
 55	            insertIntoLeaf(key);
 56	            return;
 57	        }
 58	
 59	        insertIntoChild(key);
 60	    }
 61	
 62	    private void insertIntoLeaf(int key) {
 63	        insertKeyAt(insertionPosition(key), key);
 64	    }
 65	
 66	    private void insertIntoChild(int key) {
 67	        int childIndex = insertionPosition(key);
 68	        childIndex = prepareChildForInsert(childIndex, key);
 69	        children[childIndex].insertNonFull(key);
 70	    }
 71	
 72	    private int prepareChildForInsert(int childIndex, int key) {
 73	        if (!children[childIndex].isFull()) {
 74	            return childIndex;
 75	        }
 76	
 77	        splitChild(childIndex, children[childIndex]);
 78	        return shouldInsertIntoRightChild(childIndex, key) ? childIndex + 1 : childIndex;
 79	    }
 80	
 81	    void splitChild(int childIndex, BTreeNode child) {
 82	        BTreeNode rightSibling = createRightSibling(child);
 83	        int medianKey = medianKey(child);
 84	        trimToLeftHalf(child);
 85	        insertChildAt(childIndex + 1, rightSibling);
 86	        insertKeyAt(childIndex, medianKey);
 87	    }
 88	
 89	    private BTreeNode createRightSibling(BTreeNode node) {
 90	        BTreeNode sibling = new BTreeNode(node.minimumDegree, node.leaf);
 91	        sibling.keyCount = node.minimumDegree - 1;
 92	        System.arraycopy(node.keys, node.minimumDegree, sibling.keys, 0, node.minimumDegree - 1);
 93	        if (!node.leaf) {
 94	            System.arraycopy(node.children, node.minimumDegree, sibling.children, 0, node.minimumDegree);
 95	        }
 96	        return sibling;
 97	    }
 98	
 99	    private int medianKey(BTreeNode node) {
100	        return node.keys[node.minimumDegree - 1];
101	    }
102	
103	    private void trimToLeftHalf(BTreeNode node) {
104	        node.keyCount = node.minimumDegree - 1;
105	    }
106	
107	    private void insertChildAt(int index, BTreeNode child) {
108	        shiftChildrenRight(index);
109	        children[index] = child;
110	    }
111	
112	    private void insertKeyAt(int index, int key) {
113	        shiftKeysRight(index);
114	        keys[index] = key;
115	        keyCount++;
116	    }
117	
118	    private void shiftKeysRight(int fromIndex) {
119	        System.arraycopy(keys, fromIndex, keys, fromIndex + 1, keyCount - fromIndex);
120	    }
121	
122	    private void shiftChildrenRight(int fromIndex) {
123	        System.arraycopy(children, fromIndex, children, fromIndex + 1, keyCount - fromIndex + 1);
124	    }
