126	    void traverse() {
127	        StringBuilder traversal = new StringBuilder();
128	        appendTraversal(traversal);
129	        System.out.print(traversal);
130	    }
131	
132	    void appendTraversal(StringBuilder traversal) {
133	        for (int index = 0; index < keyCount; index++) {
134	            if (!leaf) {
135	                children[index].appendTraversal(traversal);
136	            }
137	            traversal.append(' ').append(keys[index]);
138	        }
139	        if (!leaf) {
140	            children[keyCount].appendTraversal(traversal);
141	        }
142	    }
