144	    BTreeNode search(int key) {
145	        int index = searchPosition(key);
146	        if (hasKeyAt(index, key)) {
147	            return this;
148	        }
149	        if (leaf) {
150	            return null;
151	        }
152	        return children[index].search(key);
153	    }
154	
155	    private boolean hasKeyAt(int index, int key) {
156	        return index < keyCount && key == keys[index];
157	    }
158	
159	    private int searchPosition(int key) {
160	        int index = 0;
161	        while (index < keyCount && key > keys[index]) {
162	            index++;
163	        }
164	        return index;
165	    }
166	
167	    void insertAfterRootSplit(int key) {
168	        int childIndex = shouldInsertIntoRightChild(0, key) ? 1 : 0;
169	        children[childIndex].insertNonFull(key);
170	    }
171	
172	    private boolean shouldInsertIntoRightChild(int childIndex, int key) {
173	        return keys[childIndex] < key;
174	    }
175	}
