177	class BTree {
178	    private BTreeNode root;
179	    private final int minimumDegree;
180	
181	    public BTree(int minimumDegree) {
182	        this.root = null;
183	        this.minimumDegree = minimumDegree;
184	    }
185	
186	    String traversal() {
187	        StringBuilder traversal = new StringBuilder();
188	        if (!isEmpty()) {
189	            root.appendTraversal(traversal);
190	        }
191	        return traversal.toString();
192	    }
193	
194	    void traverse() {
195	        System.out.print(traversal());
196	    }
197	
198	    BTreeNode search(int key) {
199	        return isEmpty() ? null : root.search(key);
200	    }
201	
202	    boolean contains(int key) {
203	        return search(key) != null;
204	    }
205	
206	    void insertAll(int[] keys) {
207	        for (int key : keys) {
208	            insert(key);
209	        }
210	    }
211	
212	    void insert(int key) {
213	        if (isEmpty()) {
214	            createRoot(key);
215	            return;
216	        }
217	
218	        if (root.isFull()) {
219	            splitRootAndInsert(key);
220	            return;
221	        }
222	
223	        root.insertNonFull(key);
224	    }
225	
226	    private boolean isEmpty() {
227	        return root == null;
228	    }
229	
230	    private void createRoot(int key) {
231	        root = BTreeNode.leafWithSingleKey(minimumDegree, key);
232	    }
233	
234	    private void splitRootAndInsert(int key) {
235	        BTreeNode newRoot = splitRoot();
236	        newRoot.insertAfterRootSplit(key);
237	        root = newRoot;
238	    }
239	
240	    private BTreeNode splitRoot() {
241	        BTreeNode newRoot = BTreeNode.internalRootWithFirstChild(minimumDegree, root);
242	        newRoot.splitChild(0, root);
243	        return newRoot;
244	    }
245	}
